INSERT INTO shipping_rule (shop_id,zone,std_cents,free_from_cents,threshold_mode,max_weight_g,over_weight_note,status,source_url,notes,verified_at,verified_until,valid_from,valid_to) VALUES ('animaliapet','IT',NULL,NULL,'unknown',NULL,'Da verificare: il sito pubblicizza gratuità oltre 69 €, mentre l’informativa indica 5,99 € per tutti gli importi, maggiorazioni oltre 30 kg e tariffe diverse per alcune località. Non calcoliamo un totale automatico.','uncertain','https://www.animaliapet.eu/policies/shipping-policy','Consegna standard Italia, esclusi CAP disagiati, isole minori, servizi opzionali e zone escluse. Nel comparatore si applica alla quantità di una singola offerta; nella lista risparmio la soglia e il peso sono calcolati una volta per ordine del singolo negozio. Non è un preventivo del checkout.
INSERT INTO shipping_rule (shop_id,zone,std_cents,free_from_cents,threshold_mode,max_weight_g,over_weight_note,status,source_url,notes,verified_at,verified_until,valid_from,valid_to) VALUES ('bauzaar','IT',690,5900,'unknown',35000,'6,90 € sotto 59 €. Gratis oltre 59 € e fino a 35 kg di peso di spedizione. Supplementi per peso e alcune località; importo esatto a 59 € da verificare.','verified','https://www.bauzaar.it/pages/tempi-di-evasione','Consegna standard Italia, esclusi CAP disagiati, isole minori, servizi opzionali e zone escluse. Nel comparatore si applica alla quantità di una singola offerta; nella lista risparmio la soglia e il peso sono calcolati una volta per ordine del singolo negozio. Non è un preventivo del checkout.
