INSERT INTO shipping_rule (shop_id,zone,std_cents,free_from_cents,threshold_mode,max_weight_g,over_weight_note,status,source_url,notes,verified_at,verified_until,valid_from,valid_to) VALUES ('paco','IT',590,7900,'unknown',NULL,'Consegna standard a domicilio con Poste: 5,90 € fino alla soglia; gratuita oltre 79 €. A 79 € esatti la formulazione è ambigua: verifica il checkout. Esclusi altri corrieri, località disagiate, isole minori, codici sconto, carnet e servizi opzionali. Fonte: pagina Spedizione e Consegna collegata dal footer corrente e FAQ italiane, non la vecchia pagina /it/1.','verified','https://www.pacopetshop.it/it/cms/7/spedizione-consegna-paco','Consegna standard Italia, esclusi CAP disagiati, isole minori, servizi opzionali e zone escluse. Nel comparatore si applica alla quantità di una singola offerta; nella lista risparmio la soglia e il peso sono calcolati una volta per ordine del singolo negozio. Non è un preventivo del checkout.
INSERT INTO shipping_rule (shop_id,zone,std_cents,free_from_cents,threshold_mode,max_weight_g,over_weight_note,status,source_url,notes,verified_at,verified_until,valid_from,valid_to) VALUES ('webpet','IT',590,3990,'inclusive',NULL,'5,90 € sotto 39,90 €; gratuita da 39,90 €. Servizi opzionali esclusi.','verified','https://www.webpet.it/policies/shipping-policy','Consegna standard Italia, esclusi CAP disagiati, isole minori, servizi opzionali e zone escluse. Nel comparatore si applica alla quantità di una singola offerta; nella lista risparmio la soglia e il peso sono calcolati una volta per ordine del singolo negozio. Non è un preventivo del checkout.
